import test from 'node:test';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
const load = file => import(pathToFileURL(`${process.env.PROJETO}/src/${file}`).href);
const { validarCPF } = await load('cpf.js');

// Valid CPFs generated by the official algorithm, including check digits that are 0.
function gerar(base) {
  const d = base.split('').map(Number);
  const dig = n => {
    let s = 0;
    for (let i = 0; i < n; i++) s += d[i] * (n + 1 - i);
    const r = (s * 10) % 11;
    return r === 10 ? 0 : r;
  };
  d.push(dig(9));
  d.push(dig(10));
  return d.join('');
}

test('formatado valido', () => assert.equal(validarCPF('529.982.247-25'), true));
test('so digitos valido', () => assert.equal(validarCPF('52998224725'), true));
test('gerados validos', () => {
  for (const b of ['123456789', '000000001', '987654321', '100000000', '314159265']) assert.equal(validarCPF(gerar(b)), true, gerar(b));
});
test('verificador 0 valido', () => {
  const comZero = [];
  for (let i = 100000000; comZero.length < 4; i += 7919) {
    const c = gerar(String(i));
    if (c[9] === '0' || c[10] === '0') comZero.push(c);
  }
  for (const c of comZero) assert.equal(validarCPF(c), true, c);
});
test('digito errado', () => assert.equal(validarCPF('529.982.247-24'), false));
test('todos iguais', () => {
  for (let i = 0; i <= 9; i++) assert.equal(validarCPF(String(i).repeat(11)), false);
});
test('tamanho errado', () => {
  assert.equal(validarCPF('5299822472'), false);
  assert.equal(validarCPF('529982247250'), false);
});
test('caractere estranho', () => {
  assert.equal(validarCPF('529.982.247-2a'), false);
  assert.equal(validarCPF(' 52998224725'), false);
  assert.equal(validarCPF('529/982/247-25'), false);
});
test('nao string', () => {
  assert.equal(validarCPF(null), false);
  assert.equal(validarCPF(undefined), false);
  assert.equal(validarCPF(52998224725), false);
});
test('vazio', () => assert.equal(validarCPF(''), false));
